/* English build of cables.js — generated by cli/i18n.php, do not edit */
/*
 * Cable test: Device ports, Test Port, الفحص العميق, and View Result:
 * رسم للكابل بأزواجه الأربعة وطوله ومكان القطع or التماس بالمتر, والنتائج, and Link state وPoE, والعدّادات and Outages.
 */
(function (window, document) {
  'use strict';
  var box = document.querySelector('[data-cb]');
  var modal = document.getElementById('m-cable');
  if (!box || !modal || !window.SN) { return; }
  var esc = SN.esc, icon = SN.icon, num = SN.fmtNum;
  var portsBox = box.querySelector('[data-cb-ports]');
  var pick = box.querySelector('[data-cb-router]');
  var canDeep = box.getAttribute('data-can-deep') === '1';
  var current = { router: pick ? +pick.value : 0, routerName: '', port: '', mode: 'test' };
  var busy = false;
  var LEVEL = { ok: ['Fine', 'circle-check'], warn: ['Needs attention', 'triangle-alert'], bad: ['Fault', 'circle-x'], info: ['Info', 'info'] };
  var metres = function (m) { return num(m) + ' m'; };

  // ---------------- Ports ----------------
  function portTile(p) {
    var state = p.disabled ? 'is-off' : (p.running ? 'is-up' : 'is-down');
    var label = p.disabled ? 'Disabled' : (p.running ? 'Connected' : 'No link');
    var tags = (p.wan ? '<span class="badge badge-info">WAN</span>' : '') + (p.sfp ? '<span class="badge badge-outline">SFP</span>' : '');
    var meta = [];
    if (p.errors > 0) { meta.push('<span class="cb-port-err" title="Errors recorded since device boot">' + icon('triangle-alert', 'icon-sm') + num(p.errors) + ' errors</span>'); }
    if (p.link_downs > 0) { meta.push('<span title="Link drops since device boot">' + icon('unplug', 'icon-sm') + num(p.link_downs) + ' drops</span>'); }
    var last = p.last ? '<span class="cb-port-last is-' + esc(p.last.level) + '"><i></i>' + esc(LEVEL[p.last.level][0]) + ' · ' + esc(p.last.ago) + '</span>'
      : '<span class="cb-port-last is-none"><i></i>Not tested yet</span>';
    return '<button type="button" class="cb-port ' + state + '" data-port="' + esc(p.name) + '" title="' + esc(p.last ? p.last.summary : 'Test ' + p.name) + '">'
      + '<span class="cb-jack" aria-hidden="true"><i></i></span>'
      + '<span class="cb-port-top"><bdi class="cb-port-name">' + esc(p.name) + '</bdi>' + tags + '</span>'
      + (p.comment ? '<span class="cb-port-note">' + esc(p.comment) + '</span>' : '')
      + peerLine(p.peer)
      + '<span class="cb-port-state"><i></i>' + label + '</span>'
      + (meta.length ? '<span class="cb-port-meta">' + meta.join('') + '</span>' : '')
      + last + '</button>';
  }
  // سطر “to أين يذهب الكابل” in بطاقة Port
  function peerLine(peer) {
    if (!peer) { return ''; }
    if (peer.kind === 'many') { return '<span class="cb-port-peer is-many">' + icon('users', 'icon-sm') + '<span>behind it ' + num(peer.macs) + ' devices (a switch or network)</span></span>'; }
    return '<span class="cb-port-peer' + (peer.remembered ? ' is-old' : '') + '" title="' + esc(peer.remembered ? 'Last device known on this port' : 'Device on the other end') + '">'
      + icon(peer.system ? 'router' : 'arrow-left-right', 'icon-sm') + '<span><b>' + esc(peer.name) + '</b>' + (peer.remote_port ? ' · <bdi class="cb-mono">' + esc(peer.remote_port) + '</bdi>' : '') + '</span></span>';
  }
  function loadPorts() {
    if (!pick) { return; }
    current.router = +pick.value;
    var err = box.querySelector('[data-cb-ports-error]');
    err.hidden = true;
    portsBox.classList.add('is-loading');
    SN.api(box.getAttribute('data-ports') + '?router=' + current.router, { silent: true })
      .then(function (r) {
        current.routerName = r.router.name;
        portsBox.innerHTML = r.ports.length ? r.ports.map(portTile).join('')
          : '<div class="empty">' + icon('ethernet-port') + '<div class="empty-title">No Ethernet ports on this device</div></div>';
      })
      .catch(function (e) {
        portsBox.innerHTML = '';
        box.querySelector('[data-cb-ports-msg]').textContent = e.message;
        err.hidden = false;
      })
      .then(function () { portsBox.classList.remove('is-loading'); });
    try { history.replaceState(null, '', location.pathname + '?router=' + current.router); } catch (e) { /* تجاهل */ }
  }
  if (pick) {
    pick.addEventListener('change', loadPorts);
    box.querySelector('[data-cb-reload]').addEventListener('click', loadPorts);
    loadPorts();
  }
  portsBox && portsBox.addEventListener('click', function (e) {
    var t = e.target.closest('.cb-port[data-port]');
    if (t) { run(t.getAttribute('data-port'), 'test'); }
  });

  // ---------------- النافذة ----------------
  function state(s, mode) {
    modal.querySelector('[data-cb-loading]').hidden = s !== 'loading';
    modal.querySelector('[data-cb-error]').hidden = s !== 'error';
    modal.querySelector('[data-cb-result]').hidden = s !== 'done';
    modal.querySelector('[data-cb-again]').hidden = s === 'loading' || !current.port || current.saved;
    if (s === 'loading') {
      modal.querySelector('[data-cb-loading-title]').textContent = mode === 'deep' ? 'Deep test: measures the pairs' : 'Reading the port status';
      modal.querySelector('[data-cb-loading-note]').textContent = mode === 'deep'
        ? 'Disconnects the port for two seconds to measure the cable length and the location of a cut or short, then restores it immediately'
        : 'Link state, speed, PoE power, error counters and link drops · Read only';
      modal.querySelector('.cb-loading').classList.toggle('is-deep', mode === 'deep');
    }
  }
  function title(port, extra) {
    modal.querySelector('[data-cb-title]').innerHTML = 'Test port <bdi class="cb-mono">' + esc(port) + '</bdi>' + (extra ? ' · ' + esc(extra) : '');
  }
  function run(port, mode) {
    if (busy) { return; }
    busy = true;
    current.port = port; current.mode = mode; current.saved = false;
    title(port, current.routerName);
    state('loading', mode);
    if (!modal.open) { SN.openModal(modal); }
    var url = box.getAttribute(mode === 'deep' ? 'data-deep' : 'data-test');
    SN.api(url, { method: 'POST', data: { router_id: current.router, port: port, confirm: mode === 'deep' ? 1 : 0 }, silent: true })
      .then(function (r) { render(r.result); state('done'); })
      .catch(function (e) { modal.querySelector('[data-cb-error-msg]').textContent = e.message; state('error'); })
      .then(function () { busy = false; refreshTile(); });
  }
  // yet الفحص تتحدّث بطاقة Last check دون Redo تحميل Page
  function refreshTile() {
    if (!pick || !current.port) { return; }
    SN.api(box.getAttribute('data-ports') + '?router=' + current.router, { silent: true }).then(function (r) {
      portsBox.innerHTML = r.ports.map(portTile).join('');
    }).catch(function () {});
  }
  modal.querySelector('[data-cb-again]').addEventListener('click', function () { if (current.port) { run(current.port, 'test'); } });
  document.addEventListener('click', function (e) {
    var h = e.target.closest('[data-cb-open]');
    if (!h) { return; }
    var id = h.getAttribute('data-cb-open');
    current.saved = true; current.port = '';
    title('…');
    state('loading');
    SN.openModal(modal);
    SN.api(box.getAttribute('data-check').replace(/0$/, id), { silent: true })
      .then(function (r) { title(r.result.port, r.result.router); render(r.result); state('done'); })
      .catch(function (err) { modal.querySelector('[data-cb-error-msg]').textContent = err.message; state('error'); });
  });

  // ---------------- Show ----------------
  function kv(rows) {
    return '<dl class="cb-kv">' + rows.map(function (r) { return '<div><dt>' + esc(r[0]) + '</dt><dd>' + esc(r[1]) + '</dd></div>'; }).join('') + '</dl>';
  }
  function section(ic, head, body, extra) {
    return '<section class="cb-sec' + (extra ? ' ' + extra : '') + '"><h4>' + icon(ic) + esc(head) + '</h4>' + body + '</section>';
  }
  // رسم الكابل: Device in جهة Start, and Other end in جهة End, وكل زوج بطوله المقاس وعلامة القطع or التماس
  function cable(r) {
    var pairs = r.pairs || [];
    var dists = pairs.map(function (p) { return p.m; }).filter(function (m) { return m !== null && m !== undefined; });
    var L = Math.max.apply(null, dists.concat([r.length || 0, 0]));
    var scaled = L > 2;
    var rows = pairs.map(function (p) {
      var pct = scaled && p.m !== null && p.m !== undefined ? Math.max(2, Math.min(100, p.m / L * 100)) : 100;
      var cut = p.cls === 'bad' && p.state === 'open';
      var shortP = p.state === 'short';
      var fill = p.cls === 'muted' ? 100 : pct;
      var mark = '';
      if ((cut || shortP) && p.m !== null) {
        mark = '<span class="cb-mark ' + (shortP ? 'is-short' : 'is-cut') + '" style="inset-inline-start:' + pct + '%">' + icon(shortP ? 'zap' : 'scissors', 'icon-sm') + '<em>' + metres(p.m) + '</em></span>';
      } else if (p.state === 'open' && p.m !== null && p.cls !== 'muted') {
        // نهاية Pair: علامة, ومسافتها مكتوبة إلا إذا كانت Cable length نفسه (مذكور تحت الرسم)
        mark = '<span class="cb-mark is-end" style="inset-inline-start:' + pct + '%">' + (p.m === r.length ? '' : '<em>' + metres(p.m) + '</em>') + '</span>';
      }
      var dist = p.m !== null && p.m !== undefined ? ' · ' + metres(p.m) : '';
      return '<div class="cb-pair is-' + esc(p.cls) + '">'
        + '<div class="cb-pair-info"><i class="cb-pair-dot" style="--c:' + esc(p.hex) + '"></i><b>Pair ' + num(p.no) + '</b><span>' + esc(p.color) + ' · <bdi>' + esc(p.pins) + '</bdi></span></div>'
        + '<div class="cb-wire' + (cut || shortP ? ' has-fault' : '') + '" style="--c:' + esc(p.hex) + '"><span class="cb-wire-fill" style="width:' + fill + '%"></span>' + mark + '</div>'
        + '<div class="cb-pair-state">' + esc(p.text) + dist + '</div></div>';
    }).join('');
    var scale = scaled ? '<div class="cb-scale" aria-hidden="true"><span>0 m</span><span>' + metres(Math.round(L / 2)) + '</span><span>' + metres(L) + '</span></div>' : '';
    var lenLine = r.length ? '<div class="cb-length">' + icon('ruler') + '<span>Cable length</span><b>' + metres(r.length) + '</b></div>'
      : (r.prev_length ? '<div class="cb-length is-prev">' + icon('ruler') + '<span>Last measured length of this cable</span><b>' + metres(r.prev_length) + '</b></div>' : '');
    return '<div class="cb-cable"><div class="cb-ends"><span>' + icon('router', 'icon-sm') + 'Device · <bdi class="cb-mono">' + esc(r.port) + '</bdi></span><span>Other end' + icon('ethernet-port', 'icon-sm') + '</span></div>'
      + rows + scale + '</div>' + lenLine;
  }
  // الأسلاك الثمانية كما تُرى in الرأس (الطرف 1 يساراً, معيار T568B), وتحتها حالة Every سلك
  function wires(list) {
    var mark = { bad: 'circle-x', warn: 'triangle-alert', ok: 'circle-check', muted: 'minus' };
    var cols = list.map(function (w) {
      return '<div class="cb-w is-' + esc(w.cls) + '" style="--c:' + esc(w.hex) + '" title="' + esc('Wire ' + w.pin + ' · ' + w.color + ' · ' + w.text) + '">'
        + '<span class="cb-w-pin">' + num(w.pin) + '</span><i class="cb-w-line' + (w.striped ? ' is-striped' : '') + '"></i>'
        + '<span class="cb-w-mark">' + icon(mark[w.cls] || 'minus', 'icon-sm') + '</span></div>';
    }).join('');
    var rows = list.map(function (w) {
      return '<li class="is-' + esc(w.cls) + '"><i class="cb-w-chip' + (w.striped ? ' is-striped' : '') + '" style="--c:' + esc(w.hex) + '"></i>'
        + '<b>Wire ' + num(w.pin) + '</b><span class="cb-w-color">' + esc(w.color) + ' · Pair ' + num(w.pair) + '</span><em>' + esc(w.text) + '</em></li>';
    }).join('');
    return '<div class="cb-rj"><div class="cb-rj-wires" dir="ltr">' + cols + '</div><div class="cb-rj-plug" aria-hidden="true"><span>RJ45 · T568B</span></div></div>'
      + '<ul class="cb-w-list">' + rows + '</ul>'
      + '<p class="cb-w-note">' + icon('info', 'icon-sm') + '<span>The device measures each pair (two twisted wires) together: if one of the two wires is cut, the cut shows on both because the device cannot tell them apart, and a short means the two wires of the pair touch at the stated distance.</span></p>';
  }
  function counters(r) {
    var list = r.counters || [];
    if (!list.length) { return ''; }
    var hot = function (c) { return c.group !== 'other' && ((c.now || 0) > 0 || (c.since || 0) > 0); };
    var shown = list.filter(function (c) { return c.total > 0 || hot(c); });
    var cell = function (v, isHot) { return v === null || v === undefined ? '<td class="text-muted">—</td>' : '<td class="' + (v > 0 && isHot ? 'is-up' : '') + '"><bdi>' + (v > 0 ? '+' : '') + num(v) + '</bdi></td>'; };
    var row = function (c) {
      return '<tr class="' + (hot(c) ? 'is-hot' : '') + '"><th><span>' + esc(c.label) + '</span><bdi class="cb-mono">' + esc(c.key) + '</bdi></th><td><bdi>' + num(c.total) + '</bdi></td>'
        + cell(c.now, true) + cell(c.since, true) + '</tr>';
    };
    var head = '<thead><tr><th>Counter</th><th>since boot</th><th>During the test</th><th>since the previous test</th></tr></thead>';
    var body = shown.length ? '<div class="table-wrap"><table class="table cb-counters">' + head + '<tbody>' + shown.map(row).join('') + '</tbody></table></div>'
      : '<p class="cb-clean">' + icon('circle-check', 'icon-sm') + 'No errors recorded on the port since the device booted.</p>';
    var rest = list.filter(function (c) { return shown.indexOf(c) === -1; });
    if (rest.length) {
      body += '<details class="cb-more"><summary>All counters (' + num(list.length) + ')</summary><div class="table-wrap"><table class="table cb-counters">' + head + '<tbody>' + list.map(row).join('') + '</tbody></table></div></details>';
    }
    return section('activity', 'Error counters', body);
  }
  function deepBox(r) {
    var o = r.deep_offer;
    if (!o) { return ''; }
    if (!o.ok) {
      return '<div class="cb-deep is-blocked">' + icon('shield-check') + '<div><b>Measuring length and fault location is not available on this port</b><p>' + esc(o.reason) + '</p></div></div>';
    }
    if (!canDeep) { return ''; }
    return '<div class="cb-deep">' + icon('ruler') + '<div><b>Measure the cable length and the location of any cut or short in meters</b>'
      + '<p>The link is up, and the device measures pairs only when the link is down. The deep test disconnects the port for two seconds and restores it immediately, and sets a safety timer on the device that restores it automatically within 45 seconds even if the connection drops.</p>'
      + (o.poe ? '<p class="cb-deep-warn">' + icon('zap', 'icon-sm') + 'This port powers the other device (PoE): it will turn off and boot again, returning within a minute or two.</p>'
        : '<p class="cb-deep-warn">' + icon('triangle-alert', 'icon-sm') + 'The device connected to this port loses its connection for a few seconds.</p>')
      + '<button type="button" class="btn btn-primary" data-cb-deep>' + icon('ruler') + 'Deep test</button></div></div>';
  }
  // مسار الكابل: from هذا Device and Its port to Device الآخر and Its port
  function route(r) {
    var peer = r.peer;
    var here = '<div class="cb-end"><span class="cb-end-icon">' + icon('router') + '</span><div><b>' + esc(r.router || current.routerName) + '</b><span>Port <bdi class="cb-mono">' + esc(r.port) + '</bdi>'
      + (r.comment ? ' · ' + esc(r.comment) : '') + '</span></div></div>';
    var far;
    if (peer && peer.kind === 'many') {
      far = '<div class="cb-end is-far"><span class="cb-end-icon">' + icon('users') + '</span><div><b>' + num(peer.macs) + ' devices behind the port</b><span>A switch or a whole network</span></div></div>';
    } else if (peer) {
      var nameHtml = peer.system ? '<a href="' + esc(SN.base + '/routers/' + peer.system.id) + '">' + esc(peer.name) + '</a>' : esc(peer.name);
      far = '<div class="cb-end is-far' + (peer.remembered ? ' is-old' : '') + '"><span class="cb-end-icon">' + icon(peer.kind === 'host' ? 'smartphone' : 'router') + '</span><div><b>' + nameHtml + '</b><span>'
        + (peer.remote_port ? 'Port <bdi class="cb-mono">' + esc(peer.remote_port) + '</bdi>' : (peer.address ? '<bdi class="cb-mono">' + esc(peer.address) + '</bdi>' : ''))
        + (peer.remembered ? ' · Last known' : '') + '</span></div></div>';
    } else {
      far = '<div class="cb-end is-far is-unknown"><span class="cb-end-icon">' + icon('circle-help') + '</span><div><b>Other end unknown</b><span>Its device does not announce itself (MNDP/LLDP/CDP)</span></div></div>';
    }
    var len = r.length ? metres(r.length) : (r.prev_length ? metres(r.prev_length) : '');
    return '<div class="cb-route">' + here + '<div class="cb-route-line is-' + esc(r.level) + '"><i></i>' + (len ? '<em>' + icon('ruler', 'icon-sm') + len + '</em>' : '') + '</div>' + far + '</div>';
  }
  function peerInfo(peer) {
    if (!peer || peer.kind === 'many') { return ''; }
    var rows = [];
    if (peer.system) { rows.push(['Device in the system', peer.system.name]); }
    if (peer.identity && peer.identity !== peer.name) { rows.push(['Device name (identity)', peer.identity]); }
    if (peer.model) { rows.push(['Model', peer.model]); }
    if (peer.platform || peer.version) { rows.push(['System', [peer.platform, peer.version].filter(Boolean).join(' ')]); }
    if (peer.remote_port) { rows.push(['Its port', peer.remote_port]); }
    if (peer.address) { rows.push(['Address', peer.address]); }
    if (peer.mac) { rows.push(['MAC', peer.mac]); }
    if (peer.via) { rows.push(['Known via', peer.via]); }
    if (peer.others > 0) { rows.push(['Other devices discovered on the port', num(peer.others)]); }
    if (peer.remembered) { rows.push(['Last seen', String(peer.seen || '').slice(0, 16)]); }
    return rows.length ? section(peer.kind === 'host' ? 'smartphone' : 'router', peer.remembered ? 'Other end (last known)' : 'Other end', kv(rows)) : '';
  }
  function render(r) {
    var lv = LEVEL[r.level] || LEVEL.ok;
    var sub = [r.router || current.routerName, r.saved ? r.saved.ago : 'Now'];
    if (r.deep) { sub.push('Deep test'); }
    if (r.saved && r.saved.source === 'auto') { sub.push('Periodic check'); }
    if (r.comment) { sub.unshift(r.comment); }
    var html = '<div class="cb-verdict is-' + esc(r.level) + '"><span class="cb-verdict-icon">' + icon(lv[1]) + '</span><div><span class="cb-verdict-level">' + esc(lv[0]) + '</span><b>'
      + esc(r.headline) + '</b><span class="cb-verdict-sub">' + sub.filter(Boolean).map(esc).join(' · ') + '</span></div></div>';
    html += route(r);
    if (r.pairs && r.pairs.length) {
      html += section('cable', 'Pairs & length', cable(r));
      if (r.wires && r.wires.length) { html += section('ethernet-port', 'The eight wires in the connector', wires(r.wires)); }
    }
    var findings = (r.findings || []).filter(function (f, i) { return !(i === 0 && f.text === r.headline && r.level !== 'ok'); });
    if (findings.length) {
      html += section('scan-line', 'Diagnosis', '<ul class="cb-findings">' + findings.map(function (f) {
        return '<li class="is-' + esc(f.level) + '">' + icon((LEVEL[f.level] || LEVEL.info)[1], 'icon-sm') + '<span>' + esc(f.text) + '</span></li>';
      }).join('') + '</ul>');
    }
    html += deepBox(r);
    var side = peerInfo(r.peer);
    if (r.link && r.link.length) { side += section('gauge', 'Link state', kv(r.link)); }
    if (r.sfp && r.sfp.length) { side += section('zap', 'Module SFP', kv(r.sfp)); }
    if (r.links && r.links.length) { side += section('unplug', 'Link drops', kv(r.links)); }
    if (side) { html += '<div class="cb-cols">' + side + '</div>'; }
    html += counters(r);
    var out = modal.querySelector('[data-cb-result]');
    out.innerHTML = html;
    var deep = out.querySelector('[data-cb-deep]');
    if (deep) {
      deep.addEventListener('click', function () {
        SN.confirm('Deep test of port ' + r.port + ': The port will be disconnected for two seconds then restored' + (r.deep_offer.poe ? ', and the device it powers will boot again (a minute or two).' : '.') + ' Continue?',
          { okText: 'Test now', danger: false })
          .then(function (yes) { if (yes) { run(r.port, 'deep'); } });
      });
    }
    var body = modal.querySelector('.modal-body');
    if (body) { body.scrollTop = 0; }
  }
})(window, document);
